Status Stepper::dispatch(uint8_t cmd_id, std::span<const uint8_t> args, Reply &)
{
    switch (cmd_id) {
    case kCmdMoveTo: {
        const auto a = decode_stepper_move_to_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return move_to(*a);
    }
    case kCmdMoveBy: {
        const auto a = decode_stepper_move_by_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return move_by(*a);
    }
    case kCmdJog: {
        const auto a = decode_stepper_jog_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return jog(*a);
    }
    case kCmdStop: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        return stop();
    }
    case kCmdHalt: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        return halt();
    }
    case kCmdHold: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        return hold();
    }
    case kCmdRelease: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        return release();
    }
    case kCmdZero: {
        const auto a = decode_stepper_zero_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return zero(*a);
    }
    case kCmdConfigure: {
        const auto a = decode_stepper_configure_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return configure(*a);
    }
    case kCmdResetSettings: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        return reset_settings();
    }
#if FR_TEST_HOOKS
    case kCmdInjectFault: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        return inject_fault();
    }
#endif
    default:
        return std::unexpected(Err::unsupported);
    }
}

void Stepper::report_all()
{
    report_position(position());
    report_target(target());
    report_speed_hz(speed_hz());
    report_motion(motion());
    report_position_known(position_known());
    report_step_mode(step_mode());
    report_max_speed_hz(max_speed_hz());
    report_accel(accel());
    report_start_hz(start_hz());
    report_coil_ohm(coil_ohm());
    report_run_ma(run_ma());
    report_hold_pct(hold_pct());
    report_release_ms(release_ms());
    report_supply_mv(supply_mv());
    report_invert(invert());
    report_limits(limits());
    report_limit_min(limit_min());
    report_limit_max(limit_max());
    report_run_duty_pct(run_duty_pct());
    report_steps_per_rev(steps_per_rev());
}

void Stepper::encode_traits(fr::wire::Writer &w) const
{
    encode(traits(), w);
}

void Stepper::emit_done(const StepperDone &e, TimeUs at)
{
    if (sink_ == nullptr) {
        return;
    }
    uint8_t buf[StepperDone::kMaxSize];
    fr::wire::Writer w(buf, sizeof(buf));
    encode(e, w);
    sink_->event(port_, kEventDone, Priority::normal, w.bytes(), at, kOrdered);
}

